def clean(df):
    df = df.copy()
    for c in df.columns:
        if df[c].dtype == object:
            df[c] = df[c].astype(str).str.strip()
            df[c] = df[c].replace({'nan': pd.NA, 'None': pd.NA, '': pd.NA})
    if 'island' in df.columns:
        df['island'] = df['island'].replace({'Dram': 'Dream', 'Torgerson': 'Torgersen'})
    if 'sex' in df.columns:
        df['sex'] = df['sex'].astype(str).str.lower().replace({'nan': pd.NA, 'none': pd.NA, '': pd.NA})
    for c in ['bill_length_mm', 'bill_depth_mm', 'flipper_length_mm', 'body_mass_g', 'year']:
        if c in df.columns:
            df[c] = pd.to_numeric(
                df[c].astype(str).str.replace(',', '', regex=False).str.strip(),
                errors='coerce'
            )
    df = df.drop_duplicates()
    return df

def answer(df):
    d = clean(df)
    d = d[d['species'].astype(str).str.strip().str.lower() == 'adelie']
    d = d[d['island'].isin(['Biscoe', 'Dream', 'Torgersen'])]
    d = d.dropna(subset=['island', 'bill_length_mm'])
    out = d.groupby('island', sort=True)['bill_length_mm'].mean()
    return {str(k): float(v) for k, v in out.items()}
